// Multiempresa / SEC-04 (ESPEC_MULTIEMPRESA_V1 §8, tabela de Edges): a loja do token de gerente é decidida
// no servidor. O corpo só pode ESCOLHER entre as lojas permitidas do usuário; nunca indicar outra.

export type DecisaoLoja =
  | { ok: true; lojaId: string | null }
  | { ok: false; error: "LOJA_NAO_PERMITIDA" };

/** Regra pura (testável): body ∈ permitidas ⇒ body; body ausente ⇒ loja do usuário; senão recusa. */
export function decidirLojaToken(input: {
  lojaBody: string | null;
  lojaUsuario: string | null;
  permitidas: string[];
}): DecisaoLoja {
  const body = input.lojaBody?.trim() || null;
  if (!body) return { ok: true, lojaId: input.lojaUsuario };
  const permitidas = new Set(input.permitidas);
  if (input.lojaUsuario) permitidas.add(input.lojaUsuario);
  return permitidas.has(body) ? { ok: true, lojaId: body } : { ok: false, error: "LOJA_NAO_PERMITIDA" };
}

type Admin = {
  // deno-lint-ignore no-explicit-any
  from: (t: string) => any;
};

/**
 * Lê loja do usuário + vínculos (DONO ⇒ todas as lojas da empresa) e decide a loja do token e a empresa
 * (para escolher a senha de gerente DA EMPRESA). Tabelas multiempresa ausentes ⇒ comportamento antigo.
 */
export async function resolverEscopoGerente(
  supabase: Admin,
  userId: string,
  lojaBody: string | null,
): Promise<{ ok: true; lojaId: string | null; empresaId: string | null } | { ok: false; error: string }> {
  const { data: u } = await supabase.from("usuarios").select("loja_id, perfil, ativo").eq("id", userId).maybeSingle();
  const lojaUsuario = (u?.loja_id as string | null) ?? null;
  let permitidas: string[] = lojaUsuario ? [lojaUsuario] : [];
  const vinc = await supabase.from("usuario_vinculos").select("empresa_id, loja_id, papel").eq("usuario_id", userId)
    .eq("ativo", true);
  if (!vinc.error && Array.isArray(vinc.data)) {
    const rows = vinc.data as Array<{ empresa_id: string; loja_id: string | null; papel: string }>;
    permitidas = [...permitidas, ...rows.map((r) => r.loja_id).filter((x): x is string => !!x)];
    const empresasDono = rows.filter((r) => r.papel === "DONO").map((r) => r.empresa_id);
    if (empresasDono.length > 0) {
      const l = await supabase.from("lojas").select("id").in("empresa_id", empresasDono);
      if (!l.error && Array.isArray(l.data)) permitidas.push(...(l.data as Array<{ id: string }>).map((x) => x.id));
    }
  }
  const d = decidirLojaToken({ lojaBody, lojaUsuario, permitidas });
  if (!d.ok) return d;
  let empresaId: string | null = null;
  if (d.lojaId) {
    const l = await supabase.from("lojas").select("empresa_id").eq("id", d.lojaId).maybeSingle();
    if (!l.error) empresaId = (l.data?.empresa_id as string | null) ?? null;
  }
  return { ok: true, lojaId: d.lojaId, empresaId };
}

// @types/bcryptjs usa `export =` (sem default export), entao import default
// falha no type-check (TS1192). Porem, em runtime (Deno/esm.sh) o modulo CJS
// chega como `{ default: { compareSync, ... } }` — os metodos NAO ficam no topo
// do namespace. Ou seja: `import * as bcrypt` type-checa, mas
// `bcrypt.compareSync` e `undefined` quando executa.
//
// Foi esse o efeito de 680984c7 ("Runtime identico" na mensagem do commit era
// incorreto): `bcrypt.compareSync is not a function` derrubou toda autorizacao
// de gerente que passa por este helper. Falha fechada — negava sempre, nunca
// autorizou indevidamente.
//
// Import namespace (satisfaz o type-check) + acesso via `.default` (shape real
// do runtime) resolve os dois lados.
import * as bcrypt from "https://esm.sh/bcryptjs@2.4.3";

const bcryptImpl = (bcrypt as unknown as { default: typeof bcrypt }).default;

/**
 * Compara a senha em claro com o hash bcrypt do gerente.
 *
 * Isolada e exportada para que o teste de regressao exercite exatamente o
 * caminho usado em producao — o bug de 680984c7 passou porque nao havia
 * nenhum teste tocando esta linha.
 */
export function verificarSenhaGerenteBcrypt(senha: string, hash: string): boolean {
  return bcryptImpl.compareSync(senha, hash);
}

const RATE_WINDOW_MS = 15 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const TOKEN_TTL_MS = 5 * 60 * 1000;
const UNKNOWN_IP = "unknown-ip";
const UNKNOWN_DEVICE = "unknown-device";

export type GerenteRateScope = "USER" | "IP" | "DEVICE" | "GLOBAL";

type GerenteRateContext = {
  scope: GerenteRateScope;
  identifier: string;
  limit: number;
};

type GerenteRateLimitRow = {
  failed_count: number;
  first_attempt_at: string;
  lock_until: string | null;
};

type LoggerFn = (payload: Record<string, unknown>) => void;

type ValidateOptions = {
  supabase: any;
  senha: string;
  lojaId: string | null;
  /** Empresa da operação (multiempresa): escolhe a linha padrão de pdv_config DA EMPRESA (senha de gerente). */
  empresaId?: string | null;
  userId?: string | null;
  req: Request;
  logStage: string;
  log: LoggerFn;
  limits: {
    user?: number;
    ip: number;
    device: number;
    global: number;
  };
  tokenCreatedBy: string | null;
  persistAuthAttemptsByUser: boolean;
  /**
   * Finalidade tipada da autorização. Quando informada, o token é gravado em
   * `tokens_autorizacao_operacao` (tabela separada) preso a finalidade + alvo +
   * loja + gerente aprovador. Ausente = token legado, sem finalidade, gravado em
   * `tokens_desconto_gerente` (desconto de venda, limite de crédito, retomada).
   */
  finalidade?: TokenFinalidade | null;
  /**
   * Identidade da operação autorizada. Obrigatória quando `finalidade` é
   * informada. Sangria: id da movimentação. Pagamento AP:
   * `ap:<conta_id>:<idempotency_key>` — a mesma chave de idempotência que o
   * banco deriva e grava na movimentação.
   */
  alvoId?: string | null;
};

export type TokenFinalidade = "SANGRIA" | "PAGAMENTO_AP";

const FINALIDADES_VALIDAS: readonly string[] = ["SANGRIA", "PAGAMENTO_AP"];

export function isTokenFinalidade(valor: unknown): valor is TokenFinalidade {
  return typeof valor === "string" && FINALIDADES_VALIDAS.includes(valor);
}

type ValidateResult =
  | {
    ok: true;
    status: 200;
    body: {
      ok: true;
      token: string;
      expira_em: string;
      max_desconto_percentual: number;
      gerente_id: string;
    };
  }
  | {
    ok: false;
    // 400/403: recusas do contrato tipado (alvo ausente, solicitante inválido).
    status: 400 | 401 | 403 | 429 | 500 | 503;
    body: Record<string, unknown>;
  };

function normalizeIdentifier(value: string, fallback: string): string {
  const normalized = value.trim().toLowerCase();
  return normalized ? normalized.slice(0, 200) : fallback;
}

function extractClientIp(req: Request): string {
  const cfIp = req.headers.get("cf-connecting-ip");
  if (cfIp) return normalizeIdentifier(cfIp, UNKNOWN_IP);
  const forwarded = req.headers.get("x-forwarded-for");
  if (!forwarded) return UNKNOWN_IP;
  const firstIp = forwarded.split(",")[0] ?? "";
  return normalizeIdentifier(firstIp, UNKNOWN_IP);
}

function extractDeviceFingerprint(req: Request): string {
  const fromHeader = req.headers.get("x-device-fingerprint");
  return normalizeIdentifier(fromHeader ?? "", UNKNOWN_DEVICE);
}

function isBcryptHash(hash: unknown): hash is string {
  if (typeof hash !== "string") return false;
  return /^\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}$/.test(hash);
}

function generateToken(): string {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("");
}

async function getRateLimitRow(
  supabase: any,
  ctx: GerenteRateContext,
): Promise<GerenteRateLimitRow | null> {
  const { data, error } = await supabase
    .from("gerente_auth_rate_limits")
    .select("failed_count, first_attempt_at, lock_until")
    .eq("scope", ctx.scope)
    .eq("identifier", ctx.identifier)
    .maybeSingle();
  if (error) throw new Error(`RATE_LIMIT_READ_FAILED:${ctx.scope}:${error.message}`);
  return data as GerenteRateLimitRow | null;
}

function isLocked(lockUntil: string | null, nowMs: number): boolean {
  if (!lockUntil) return false;
  const lockMs = Date.parse(lockUntil);
  return Number.isFinite(lockMs) && lockMs > nowMs;
}

async function registerFailure(
  supabase: any,
  ctx: GerenteRateContext,
  row: GerenteRateLimitRow | null,
  now: Date,
) {
  const nowMs = now.getTime();
  const firstAttemptMs = row?.first_attempt_at ? Date.parse(row.first_attempt_at) : Number.NaN;
  const insideWindow = Number.isFinite(firstAttemptMs) && nowMs - firstAttemptMs <= RATE_WINDOW_MS;

  const failedCount = insideWindow ? (row?.failed_count ?? 0) + 1 : 1;
  const firstAttemptAt = insideWindow && row?.first_attempt_at
    ? row.first_attempt_at
    : now.toISOString();
  const lockUntil = failedCount >= ctx.limit ? new Date(nowMs + LOCK_MS).toISOString() : null;

  const { error } = await supabase.from("gerente_auth_rate_limits").upsert({
    scope: ctx.scope,
    identifier: ctx.identifier,
    failed_count: failedCount,
    first_attempt_at: firstAttemptAt,
    lock_until: lockUntil,
    updated_at: now.toISOString(),
  });
  if (error) throw new Error(`RATE_LIMIT_WRITE_FAILED:${ctx.scope}:${error.message}`);

  return { failedCount, lockUntil, blockedNow: !!lockUntil };
}

async function resetRateLimit(
  supabase: any,
  ctx: GerenteRateContext,
  nowIso: string,
) {
  const { error } = await supabase.from("gerente_auth_rate_limits").upsert({
    scope: ctx.scope,
    identifier: ctx.identifier,
    failed_count: 0,
    first_attempt_at: nowIso,
    lock_until: null,
    updated_at: nowIso,
  });
  if (error) throw new Error(`RATE_LIMIT_RESET_FAILED:${ctx.scope}:${error.message}`);
}

async function precheckRateLimitLocks(
  supabase: any,
  rateContexts: GerenteRateContext[],
  nowMs: number,
  logStage: string,
  log: LoggerFn,
): Promise<ValidateResult | null> {
  for (const ctx of rateContexts) {
    const row = await getRateLimitRow(supabase, ctx);
    if (!isLocked(row?.lock_until ?? null, nowMs)) continue;
    log({
      level: "warn",
      stage: logStage,
      event: "locked_precheck",
      scope: ctx.scope,
      identifier: ctx.identifier,
      lock_until: row?.lock_until ?? null,
    });
    return {
      ok: false,
      status: 429,
      body: {
        ok: false,
        error: "LOCKED_TEMPORARILY",
        scope: ctx.scope,
        lock_until: row?.lock_until ?? null,
      },
    };
  }
  return null;
}

type GerenteConfigBundle = {
  config: {
    gerente_id: string;
    gerente_senha_bcrypt: string | null;
    max_desconto_gerente_percentual: unknown;
  };
  gerenteIdRaw: string;
};

async function loadGerenteConfigBundle(
  supabase: any,
  logStage: string,
  log: LoggerFn,
  empresaId: string | null = null,
): Promise<GerenteConfigBundle | ValidateResult> {
  const COLS = "gerente_id, gerente_senha_bcrypt, max_desconto_gerente_percentual";
  // Multiempresa: senha de gerente é da EMPRESA da operação (linha padrão loja_id NULL da empresa).
  // Sem empresa (legado) ou coluna ainda inexistente ⇒ linha id=1, como antes (cliente 1).
  let res = empresaId
    ? await supabase.from("pdv_config").select(COLS).is("loja_id", null).eq("empresa_id", empresaId).maybeSingle()
    : await supabase.from("pdv_config").select(COLS).eq("id", 1).maybeSingle();
  if (empresaId && res.error && /empresa_id/.test(String(res.error.message))) {
    res = await supabase.from("pdv_config").select(COLS).eq("id", 1).maybeSingle();
  }
  const { data: config, error: configError } = res;

  if (configError) {
    log({ level: "error", stage: logStage, error: configError.message });
    return { ok: false, status: 500, body: { ok: false, error: "ERRO_DB_CONFIG" } };
  }
  const hasBcrypt = isBcryptHash(config?.gerente_senha_bcrypt);
  if (!config || !hasBcrypt) {
    log({ level: "error", stage: logStage, error: "CONFIG_NAO_ENCONTRADA" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_NAO_ENCONTRADA" } };
  }
  const gerenteIdRaw = typeof config.gerente_id === "string" ? config.gerente_id.trim() : "";
  if (!gerenteIdRaw) {
    log({ level: "error", stage: logStage, error: "CONFIG_GERENTE_ID_AUSENTE" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_ID_AUSENTE" } };
  }
  const { data: gerenteUser, error: gerenteErr } = await supabase
    .from("usuarios")
    .select("id, perfil, ativo")
    .eq("id", gerenteIdRaw)
    .maybeSingle();
  if (gerenteErr) {
    log({ level: "error", stage: logStage, error: "GERENTE_LOOKUP_ERROR", detail: gerenteErr.message });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_INVALIDA" } };
  }
  const perfilOk =
    gerenteUser?.ativo === true &&
    (gerenteUser.perfil === "GERENTE" || gerenteUser.perfil === "DONO" || gerenteUser.perfil === "ADMIN");
  if (!perfilOk) {
    log({ level: "error", stage: logStage, error: "CONFIG_GERENTE_INVALIDA" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_INVALIDA" } };
  }
  return { config, gerenteIdRaw };
}

async function respondSenhaGerenteInvalida(
  supabase: any,
  rateContexts: GerenteRateContext[],
  now: Date,
  logStage: string,
  log: LoggerFn,
  lojaId: string | null,
  clientIp: string,
  deviceFingerprint: string,
  persistAuthAttemptsByUser: boolean,
  userId: string | null | undefined,
  nowIso: string,
): Promise<ValidateResult> {
  let lockScope: GerenteRateScope | null = null;
  let lockUntil: string | null = null;

  for (const ctx of rateContexts) {
    const row = await getRateLimitRow(supabase, ctx);
    const result = await registerFailure(supabase, ctx, row, now);
    log({
      level: "warn",
      stage: logStage,
      event: "failed_attempt",
      scope: ctx.scope,
      identifier: ctx.identifier,
      failed_count: result.failedCount,
      lock_until: result.lockUntil,
    });
    if (result.blockedNow && !lockScope) {
      lockScope = ctx.scope;
      lockUntil = result.lockUntil;
    }
  }

  if (persistAuthAttemptsByUser && userId) {
    await supabase.from("gerente_auth_attempts").upsert({
      user_id: userId,
      failed_count: 1,
      lock_until: lockUntil,
      updated_at: nowIso,
    });
  }

  log({
    level: "warn",
    stage: logStage,
    error: "SENHA_INVALIDA",
    loja_id: lojaId,
    ip: clientIp,
    device: deviceFingerprint,
    rate_scope: lockScope,
  });

  if (lockScope && lockUntil) {
    return {
      ok: false,
      status: 429,
      body: {
        ok: false,
        error: "LOCKED_TEMPORARILY",
        scope: lockScope,
        lock_until: lockUntil,
      },
    };
  }
  return { ok: false, status: 401, body: { ok: false, error: "SENHA_INVALIDA" } };
}

async function persistTokenAndResetLimits(
  supabase: any,
  token: string,
  expiraEm: string,
  lojaId: string | null,
  tokenCreatedBy: string | null,
  rateContexts: GerenteRateContext[],
  nowIso: string,
  persistAuthAttemptsByUser: boolean,
  userId: string | null | undefined,
  logStage: string,
  log: LoggerFn,
  finalidade: TokenFinalidade | null,
  alvoId: string | null,
  gerenteAprovadorId: string,
  lojaOperacaoId: string | null,
): Promise<ValidateResult | null> {
  // Token TIPADO (sangria / pagamento AP): vai para a tabela separada, preso a
  // finalidade + alvo + loja + gerente aprovador.
  //
  // `gerenteAprovadorId` vem de `pdv_config.gerente_id`, já validado (ativo e com
  // perfil aprovador) — é quem de fato teve a senha conferida. NÃO usar
  // `tokenCreatedBy`: aquele é o usuário autenticado que PEDIU a autorização, ou
  // seja, o operador solicitante. Confundir os dois registrava o solicitante como
  // aprovador da própria operação.
  //
  // A loja é derivada do servidor (`lojaOperacaoId`), não do corpo da requisição.
  const insertResult = finalidade
    ? await supabase.from("tokens_autorizacao_operacao").insert({
      token,
      finalidade,
      alvo_id: alvoId,
      loja_id: lojaOperacaoId,
      gerente_id: gerenteAprovadorId,
      solicitante_id: tokenCreatedBy,
      expira_em: expiraEm,
      usado: false,
    })
    : await supabase.from("tokens_desconto_gerente").insert({
      token,
      expira_em: expiraEm,
      usado: false,
      loja_id: lojaId,
      criado_por: tokenCreatedBy,
    });
  const { error: insertError } = insertResult;
  if (insertError) {
    log({ level: "error", stage: logStage, error: insertError.message });
    return { ok: false, status: 503, body: { ok: false, error: "ERRO_PERSISTENCIA_TOKEN" } };
  }

  for (const ctx of rateContexts) {
    await resetRateLimit(supabase, ctx, nowIso);
  }
  if (persistAuthAttemptsByUser && userId) {
    await supabase.from("gerente_auth_attempts").upsert({
      user_id: userId,
      failed_count: 0,
      lock_until: null,
      updated_at: nowIso,
    });
  }
  return null;
}

export async function validateGerenteAndIssueToken(
  options: ValidateOptions,
): Promise<ValidateResult> {
  const {
    supabase,
    senha,
    lojaId,
    empresaId,
    userId,
    req,
    logStage,
    log,
    limits,
    tokenCreatedBy,
    persistAuthAttemptsByUser,
    finalidade,
    alvoId,
  } = options;

  const now = new Date();
  const nowIso = now.toISOString();
  const nowMs = now.getTime();
  const clientIp = extractClientIp(req);
  const deviceFingerprint = extractDeviceFingerprint(req);

  const rateContexts: GerenteRateContext[] = [];
  if (userId && limits.user) {
    rateContexts.push({ scope: "USER", identifier: userId, limit: limits.user });
  }
  rateContexts.push(
    { scope: "IP", identifier: clientIp, limit: limits.ip },
    { scope: "DEVICE", identifier: deviceFingerprint, limit: limits.device },
    { scope: "GLOBAL", identifier: "global", limit: limits.global },
  );

  try {
    const locked = await precheckRateLimitLocks(supabase, rateContexts, nowMs, logStage, log);
    if (locked) return locked;

    const bundleOrErr = await loadGerenteConfigBundle(supabase, logStage, log, empresaId ?? null);
    if ("ok" in bundleOrErr) return bundleOrErr;
    const { config, gerenteIdRaw } = bundleOrErr;

    let senhaValida = false;
    const bcryptHash = typeof config.gerente_senha_bcrypt === "string" ? config.gerente_senha_bcrypt : "";
    if (isBcryptHash(bcryptHash)) {
      senhaValida = verificarSenhaGerenteBcrypt(senha, bcryptHash);
    } else {
      log({
        level: "error",
        stage: logStage,
        error: "CONFIG_HASH_INSEGURO",
      });
      return { ok: false, status: 500, body: { ok: false, error: "CONFIG_HASH_INSEGURO" } };
    }
    if (!senhaValida) {
      return await respondSenhaGerenteInvalida(
        supabase,
        rateContexts,
        now,
        logStage,
        log,
        lojaId,
        clientIp,
        deviceFingerprint,
        persistAuthAttemptsByUser,
        userId,
        nowIso,
      );
    }

    const token = generateToken();
    const expiraEm = new Date(Date.now() + TOKEN_TTL_MS).toISOString();

    // Token tipado exige alvo e loja. A loja NÃO vem do corpo da requisição: é
    // lida do cadastro do solicitante, para que o cliente não escolha o tenant.
    let lojaOperacaoId: string | null = null;
    if (finalidade) {
      if (!alvoId || !alvoId.trim()) {
        log({ level: "error", stage: logStage, error: "ALVO_OBRIGATORIO" });
        return { ok: false, status: 400, body: { ok: false, error: "ALVO_OBRIGATORIO" } };
      }
      if (!userId) {
        log({ level: "error", stage: logStage, error: "SOLICITANTE_OBRIGATORIO" });
        return { ok: false, status: 401, body: { ok: false, error: "SOLICITANTE_OBRIGATORIO" } };
      }
      const { data: solicitante, error: solicitanteErr } = await supabase
        .from("usuarios")
        .select("loja_id, ativo")
        .eq("id", userId)
        .maybeSingle();
      if (solicitanteErr || !solicitante?.ativo || !solicitante?.loja_id) {
        log({ level: "error", stage: logStage, error: "SOLICITANTE_INVALIDO" });
        return { ok: false, status: 403, body: { ok: false, error: "SOLICITANTE_INVALIDO" } };
      }
      lojaOperacaoId = solicitante.loja_id as string;
    }

    const persistErr = await persistTokenAndResetLimits(
      supabase,
      token,
      expiraEm,
      lojaId,
      tokenCreatedBy,
      rateContexts,
      nowIso,
      persistAuthAttemptsByUser,
      userId,
      logStage,
      log,
      finalidade ?? null,
      alvoId?.trim() ?? null,
      gerenteIdRaw,
      lojaOperacaoId,
    );
    if (persistErr) return persistErr;

    log({
      level: "info",
      stage: logStage,
      success: true,
      loja_id: lojaId,
      ip: clientIp,
      device: deviceFingerprint,
    });

    const maxPct = Number(config.max_desconto_gerente_percentual);
    return {
      ok: true,
      status: 200,
      body: {
        ok: true,
        token,
        expira_em: expiraEm,
        max_desconto_percentual: Number.isFinite(maxPct) && maxPct > 0 ? maxPct : 20,
        gerente_id: gerenteIdRaw,
      },
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : "UNKNOWN_ERROR";
    log({ level: "error", stage: logStage, error: errorMsg });
    return { ok: false, status: 500, body: { ok: false, error: "ERRO_INTERNO" } };
  }
}

// Edge Function: validar-gerente
// Valida senha do gerente contra hash armazenado no banco (tabela pdv_config)
// Retorna token temporário de desconto se válido, ou erro se inválido
//
// Contrato:
// POST /functions/v1/validar-gerente
// Header: Authorization: Bearer <jwt> (usuário autenticado)
// Body: { senha: string, loja_id?: string, finalidade?: "SANGRIA"|"PAGAMENTO_AP", alvo_id?: string }
// Response: { ok: true, token: string, expira_em: string } | { ok: false, error: string }
//
// CORS:
// - VALIDAR_GERENTE_ALLOWED_ORIGINS: lista separada por vírgula, ex.:
//   https://seu-app.vercel.app,https://www.sualoja.com.br,http://localhost:3000
// - VALIDAR_GERENTE_CORS_STRICT=true (produção): com lista preenchida, só essas origens no ACAO;
//   se lista ausente ou só lixo, bloqueia qualquer requisição com header Origin. Sem Origin (curl etc.)
//   não é bloqueado por esta camada.
// - Sem STRICT e sem lista: legado Access-Control-Allow-Origin: * (só dev/homolog consciente).

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";
import { isTokenFinalidade, validateGerenteAndIssueToken } from "../_shared/gerente-auth.ts";
import { resolverEscopoGerente } from "../_shared/escopoGerente.ts";
import { logJson } from "../../../../shared/logger.ts";

const USER_LIMIT = 5;
const IP_LIMIT = 20;
const DEVICE_LIMIT = 10;
const GLOBAL_LIMIT = 60;

const CORS_ALLOW_HEADERS =
  "authorization, content-type, x-device-fingerprint";
const CORS_ALLOW_METHODS = "POST, OPTIONS";

/** Log estruturado */
const log = (payload: Record<string, unknown>) => logJson("validar-gerente", payload);

function normalizeOriginUrl(raw: string): string {
  return raw.trim().replace(/\/+$/, "");
}

function isCorsStrict(): boolean {
  const raw = Deno.env.get("VALIDAR_GERENTE_CORS_STRICT");
  const v = (raw ?? "").trim().toLowerCase();
  return v === "true" || v === "1" || v === "yes";
}

type CorsMode =
  | { kind: "wildcard" }
  | { kind: "allowlist"; origins: Set<string> };

function resolveCorsMode(): CorsMode {
  const strict = isCorsStrict();
  const raw = Deno.env.get("VALIDAR_GERENTE_ALLOWED_ORIGINS")?.trim() ?? "";

  if (!raw) {
    if (strict) return { kind: "allowlist", origins: new Set() };
    return { kind: "wildcard" };
  }

  const set = new Set<string>();
  for (const part of raw.split(",")) {
    const n = normalizeOriginUrl(part);
    if (n) set.add(n.toLowerCase());
  }

  if (set.size === 0) {
    if (strict) return { kind: "allowlist", origins: new Set() };
    return { kind: "wildcard" };
  }
  return { kind: "allowlist", origins: set };
}

/** true se o browser enviou Origin e não pode usar esta API em modo allowlist. */
function corsOriginForbidden(req: Request, mode: CorsMode): boolean {
  if (mode.kind === "wildcard") return false;
  const origin = req.headers.get("Origin") ?? req.headers.get("origin");
  if (!origin?.trim()) return false;
  return !mode.origins.has(normalizeOriginUrl(origin).toLowerCase());
}

function corsHeaders(req: Request, mode: CorsMode): Record<string, string> {
  const base: Record<string, string> = {
    "Access-Control-Allow-Headers": CORS_ALLOW_HEADERS,
    "Access-Control-Allow-Methods": CORS_ALLOW_METHODS,
    "Access-Control-Max-Age": "86400",
  };
  if (mode.kind === "wildcard") {
    base["Access-Control-Allow-Origin"] = "*";
    return base;
  }
  const origin = req.headers.get("Origin") ?? req.headers.get("origin");
  if (origin?.trim() && mode.origins.has(normalizeOriginUrl(origin).toLowerCase())) {
    base["Access-Control-Allow-Origin"] = origin.trim();
    base["Vary"] = "Origin";
  }
  return base;
}

function jsonResponse(status: number, body: unknown, req: Request, mode: CorsMode) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...corsHeaders(req, mode),
    },
  });
}

/** IP para auditoria de CORS (Edge / proxy). */
function clientIpForCorsLog(req: Request): string {
  const cf = req.headers.get("cf-connecting-ip")?.trim();
  if (cf) return cf;
  const xff = req.headers.get("x-forwarded-for")?.trim();
  if (xff) return xff.split(",")[0]?.trim() ?? "unknown";
  return "unknown";
}

function logCorsBlocked(req: Request): void {
  const origin =
    req.headers.get("Origin") ?? req.headers.get("origin") ?? "";
  const ip = clientIpForCorsLog(req);
  const ts = new Date().toISOString();
  const originLabel = origin || "(none)";
  log({
    level: "warn",
    stage: "cors",
    error: "ORIGIN_NOT_ALLOWED",
    origin: origin || null,
    ip,
    ts,
  });
}

Deno.serve(async (req) => {
  const corsMode = resolveCorsMode();

  if (req.method === "OPTIONS") {
    if (corsOriginForbidden(req, corsMode)) {
      logCorsBlocked(req);
      return new Response(null, { status: 403 });
    }
    return new Response(null, {
      status: 204,
      headers: corsHeaders(req, corsMode),
    });
  }

  if (corsOriginForbidden(req, corsMode)) {
    logCorsBlocked(req);
    return new Response(JSON.stringify({ ok: false, error: "ORIGIN_NOT_ALLOWED" }), {
      status: 403,
      headers: { "Content-Type": "application/json" },
    });
  }

  if (req.method !== "POST") {
    log({ level: "warn", stage: "http", error: "METHOD_NOT_ALLOWED" });
    return jsonResponse(405, { ok: false, error: "METHOD_NOT_ALLOWED" }, req, corsMode);
  }

  // Parse do body
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    log({ level: "warn", stage: "http", error: "INVALID_JSON" });
    return jsonResponse(400, { ok: false, error: "INVALID_JSON" }, req, corsMode);
  }

  // Validação do payload
  if (typeof body !== "object" || body === null) {
    return jsonResponse(400, { ok: false, error: "INVALID_BODY" }, req, corsMode);
  }

  const { senha, loja_id, finalidade, alvo_id } = body as {
    senha?: unknown;
    loja_id?: unknown;
    finalidade?: unknown;
    alvo_id?: unknown;
  };

  // Finalidade tipada é opcional (ausente = token legado), mas se vier tem de
  // ser uma das conhecidas e acompanhada do alvo. Valor desconhecido = recusa.
  if (finalidade !== undefined && finalidade !== null && !isTokenFinalidade(finalidade)) {
    return jsonResponse(400, { ok: false, error: "FINALIDADE_DESCONHECIDA" }, req, corsMode);
  }
  const finalidadeTipada = isTokenFinalidade(finalidade) ? finalidade : null;
  const alvoIdTexto = typeof alvo_id === "string" ? alvo_id.trim() : "";
  if (finalidadeTipada && !alvoIdTexto) {
    return jsonResponse(400, { ok: false, error: "ALVO_OBRIGATORIO" }, req, corsMode);
  }

  if (typeof senha !== "string" || !senha) {
    return jsonResponse(400, { ok: false, error: "SENHA_OBRIGATORIA" }, req, corsMode);
  }
  const senhaNormalizada = senha.trim();
  if (!senhaNormalizada || senhaNormalizada.length > 128) {
    return jsonResponse(400, { ok: false, error: "SENHA_INVALIDA_FORMATO" }, req, corsMode);
  }

  // Configurações do Supabase (service role para acessar pdv_config)
  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!supabaseUrl || !serviceRoleKey) {
    log({ level: "error", stage: "config", error: "MISSING_ENV" });
    return jsonResponse(500, { ok: false, error: "CONFIG_ERROR" }, req, corsMode);
  }

  const supabase = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  try {
    const authHeader = req.headers.get("Authorization") ?? req.headers.get("authorization");
    const bearer =
      authHeader && authHeader.startsWith("Bearer ")
        ? authHeader.slice("Bearer ".length).trim()
        : "";
    if (!bearer) {
      log({ level: "warn", stage: "auth", error: "MISSING_BEARER" });
      return jsonResponse(401, { ok: false, error: "UNAUTHORIZED" }, req, corsMode);
    }

    const { data: authData, error: authErr } = await supabase.auth.getUser(bearer);
    if (authErr || !authData.user) {
      log({
        level: "warn",
        stage: "auth",
        error: "INVALID_BEARER",
        detail: authErr?.message ?? null,
      });
      return jsonResponse(401, { ok: false, error: "UNAUTHORIZED" }, req, corsMode);
    }

    // SEC-04 (multiempresa): loja decidida no servidor; o corpo só escolhe entre as lojas permitidas.
    const escopo = await resolverEscopoGerente(
      supabase,
      authData.user.id,
      typeof loja_id === "string" ? loja_id : null,
    );
    if (!escopo.ok) {
      log({ level: "warn", stage: "auth", error: escopo.error });
      return jsonResponse(403, { ok: false, error: escopo.error }, req, corsMode);
    }

    const result = await validateGerenteAndIssueToken({
      supabase,
      senha: senhaNormalizada,
      lojaId: escopo.lojaId,
      empresaId: escopo.empresaId,
      userId: authData.user.id,
      req,
      logStage: "auth",
      log: log,
      limits: {
        user: USER_LIMIT,
        ip: IP_LIMIT,
        device: DEVICE_LIMIT,
        global: GLOBAL_LIMIT,
      },
      tokenCreatedBy: authData.user.id,
      persistAuthAttemptsByUser: true,
      finalidade: finalidadeTipada,
      alvoId: finalidadeTipada ? alvoIdTexto : null,
    });
    return jsonResponse(result.status, result.body, req, corsMode);
  } catch (e) {
    const errorMsg = e instanceof Error ? e.message : "UNKNOWN_ERROR";
    log({ level: "error", stage: "runtime", error: errorMsg });
    return jsonResponse(500, { ok: false, error: "ERRO_INTERNO" }, req, corsMode);
  }
});

/**
 * Logger unificado para todo o projeto
 * Combina funcionalidades de Edge functions, desktop e server errors
 */

export interface LogEntry {
  level: 'info' | 'warn' | 'error'
  message: string
  timestamp: string
  context?: Record<string, unknown>
  service?: string
}

const DEFAULT_SENSITIVE_KEYS = new Set(
  [
    'password',
    'senha',
    'token',
    'access_token',
    'refresh_token',
    'authorization',
    'apikey',
    'api_key',
    'secret',
    'service_role',
    'cpf',
    'cnpj',
    'documento',
    'email',
    'email_address',
  ].map((k) => k.toLowerCase()),
)

const MAX_REDACT_DEPTH = 12
const MAX_STRING_LOG_LENGTH = 200

function isSensitiveKey(key: string): boolean {
  const k = key.toLowerCase()
  if (DEFAULT_SENSITIVE_KEYS.has(k)) return true
  if (k.endsWith('_token') || k.endsWith('token')) return true
  return k.includes('password') || k.includes('senha')
}

function redactString(value: string): string {
  if (value.length <= MAX_STRING_LOG_LENGTH) return value
  return `${value.slice(0, 80)}…[truncated]`
}

function redactObject(value: Record<string, unknown>, depth: number): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(value)) {
    out[k] = isSensitiveKey(k) ? '[REDACTED]' : redactForLog(v, depth + 1)
  }
  return out
}

/**
 * Retorna uma cópia segura para log, mascarando chaves sensíveis
 */
export function redactForLog<T>(value: T, depth = 0): T {
  if (depth > MAX_REDACT_DEPTH) return '[MAX_DEPTH]' as unknown as T
  if (value === null || value === undefined) return value

  const valueType = typeof value
  if (valueType === 'string') return redactString(value as string) as unknown as T
  if (valueType === 'number' || valueType === 'boolean') return value
  if (Array.isArray(value)) {
    return (value as unknown[]).map((item) => redactForLog(item, depth + 1)) as unknown as T
  }
  if (valueType === 'object') {
    return redactObject(value as Record<string, unknown>, depth) as unknown as T
  }

  return value
}

function createLogEntry(
  level: LogEntry['level'],
  message: string,
  context?: Record<string, unknown>,
): LogEntry {
  return {
    level,
    message,
    timestamp: new Date().toISOString(),
    context,
  }
}

function writeConsole(entry: LogEntry): void {
  const prefix = `[${entry.timestamp}] ${entry.level.toUpperCase()}:`
  if (entry.level === 'error') {
    console.error(prefix, entry.message, entry.context)
    return
  }
  if (entry.level === 'warn') {
    console.warn(prefix, entry.message, entry.context)
    return
  }
  console.log(prefix, entry.message, entry.context)
}

function errorToLogPayload(err: unknown): Record<string, unknown> {
  if (err instanceof Error) {
    return { name: err.name, message: err.message, stack: err.stack }
  }
  return { thrown: err }
}

function readStoredLogs(storageKey: string): LogEntry[] {
  if (typeof globalThis === 'undefined') return []
  try {
    const raw = globalThis.localStorage.getItem(storageKey)
    if (!raw) return []
    return JSON.parse(raw) as LogEntry[]
  } catch {
    return []
  }
}

function writeStoredLogs(storageKey: string, logs: LogEntry[], maxLogs: number): void {
  if (typeof globalThis === 'undefined') return
  try {
    const bounded = logs.slice(-maxLogs)
    globalThis.localStorage.setItem(storageKey, JSON.stringify(bounded))
  } catch {
    // Persistência opcional; falhas de quota ou ambiente sem storage são ignoradas
  }
}

export class EdgeLogger {
  logJson(svc: string, payload: Record<string, unknown>): void {
    const entry = createLogEntry('info', `Service: ${svc}`, payload)
    console.log(JSON.stringify({ ts: entry.timestamp, svc, ...payload }))
  }
}

export class DesktopLogger {
  private logs: LogEntry[] = []
  private readonly maxLogs = 1000
  private readonly storageKey = 'pdv_local_logs'

  private persistLog(entry: LogEntry): void {
    const stored = readStoredLogs(this.storageKey)
    stored.push(entry)
    writeStoredLogs(this.storageKey, stored, this.maxLogs)
  }

  private pushToBuffer(entry: LogEntry): void {
    this.logs.push(entry)
    if (this.logs.length > this.maxLogs) {
      this.logs.shift()
    }
  }

  private log(level: LogEntry['level'], message: string, context?: Record<string, unknown>): void {
    const entry = createLogEntry(level, message, context)
    this.pushToBuffer(entry)
    writeConsole(entry)
    this.persistLog(entry)
  }

  info(message: string, context?: Record<string, unknown>): void {
    this.log('info', message, context)
  }

  warn(message: string, context?: Record<string, unknown>): void {
    this.log('warn', message, context)
  }

  error(message: string, context?: Record<string, unknown>): void {
    this.log('error', message, context)
  }

  getLogs(): LogEntry[] {
    return [...this.logs]
  }

  clearLogs(): void {
    this.logs = []
  }

  async getLogFileContent(): Promise<string> {
    const logs = readStoredLogs(this.storageKey)
    return logs.map((log) => JSON.stringify(log)).join('\n')
  }
}

export class ServerLogger {
  logCaughtServerError(context: string, err: unknown): void {
    const sanitizedPayload = redactForLog(errorToLogPayload(err))
    console.error(`[${context}]`, JSON.stringify(sanitizedPayload))
  }
}

export const edgeLogger = new EdgeLogger()
export const desktopLogger = new DesktopLogger()
export const serverLogger = new ServerLogger()

export function logJson(svc: string, payload: Record<string, unknown>): void {
  edgeLogger.logJson(svc, payload)
}

export function logCaughtServerError(context: string, err: unknown): void {
  serverLogger.logCaughtServerError(context, err)
}

export const logger = desktopLogger
